package com.rikkeibank.transaction.service;import org.springframework.security.core.Authentication;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.stereotype.Component;import java.util.UUID;@Component("transactionAuthorization")public class TransactionAuthorization{private final TransactionQueryService q;public TransactionAuthorization(TransactionQueryService q){this.q=q;}public boolean canRead(UUID id,Authentication auth){if(!(auth instanceof JwtAuthenticationToken j))return false;var t=q.get(id);String customer=j.getToken().getClaimAsString("customerId");return customer!=null&&t.getCustomerId().toString().equals(customer)||t.getAssignedTellerId()!=null&&t.getAssignedTellerId().toString().equals(j.getToken().getSubject());}}

